<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';
$error=null;$user=null;$permission=(string)($_GET['permission']??'');
try{$pdo=business_db();security_step17_ensure($pdo);$user=security_step17_session_user($pdo,false);if(!$user){header('Location: login.php');exit;}security_step17_audit($pdo,(int)$user['id'],'security_access_denied','route',null,['permission'=>$permission,'script'=>(string)($_SERVER['HTTP_REFERER']??'')]);}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Access Denied - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><main class="os-main" style="max-width:760px;margin:8vh auto"><section class="os-card"><span class="pp-badge warn">ACCESS CONTROL</span><h1>Permission required</h1><p>This Business OS account does not have permission to open this action or workspace.</p><?php if($permission):?><div class="pp-source"><b>Required permission</b><span><?= security_step17_h($permission) ?></span></div><?php endif;?><?php if($user):?><div class="pp-source"><b>Signed in as</b><span><?= security_step17_h($user['full_name'].' • '.strtoupper((string)$user['role_code'])) ?></span></div><?php endif;?><?php if($error):?><div class="pp-alert bad"><?= security_step17_h($error) ?></div><?php endif;?><div class="pp-actions" style="margin-top:18px"><a class="os-btn primary" href="index.php">Back to Dashboard</a><a class="os-btn" href="logout.php">Sign Out</a></div></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
